//! A TSX app's generated entry (`zant-tsx --out … --main App`).
//!
//! The generated `main.rs` declares the project's modules (one Rust file per
//! `.tsx`) and runs the default export of the entry file with the project's
//! config:
//!
//! ```ignore
//! //! Generated by zant-tsx: the app's entry (App.tsx). Do not edit.
//! #[path = "App.rs"] pub mod app;
//!
//! fn main() -> zant::Result<()> {
//!     zant::tsx::app::run::<app::Counter>(zant::tsx::app::Config {
//!         title: "Counter".into(),
//!         ..Default::default()
//!     })
//! }
//! ```
//!
//! `zant_build::tsx_app` writes the generated modules into `OUT_DIR`
//! and the app's `src/main.rs` includes this file
//! (`include!(concat!(env!("OUT_DIR"), "/main.rs"))`); `#[path]` is resolved
//! relative to the generated file's own directory, so the included entry finds
//! its sibling modules. Modules generated for hand-written `.rs` files are
//! **not** declared here: the app's crate root already declares its own
//! (`mod format;`, `mod native;`), and a second declaration would be a
//! duplicate.
//!
//! The entry wires no `app_config` / `native` modules: the generated `Config`
//! literal carries the configuration, and native modules are declared by the
//! app's own crate root.

use crate::ast;
use crate::compile::{ConfigSpec, SourceFile};
use crate::parser::Parser;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Error {
    NoEntry,
    NoRoot,
    NameTaken,
}

impl std::fmt::Display for Error {
    fn fmt(&self, fmt: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        fmt.write_str(describe(*self))
    }
}

impl std::error::Error for Error {}

pub fn describe(error: Error) -> &'static str {
    match error {
        Error::NoEntry => "no such .tsx file among the inputs",
        Error::NoRoot => "the file has no default exported component",
        Error::NameTaken => "an input is already named main.rs",
    }
}

/// The source of `main.rs` for the entry file `<name>.tsx`.
pub fn main_source(
    files: &[SourceFile],
    name: &str,
    config: Option<&ConfigSpec>,
) -> Result<String, Error> {
    let mut entry: Option<&SourceFile> = None;
    for file in files {
        if file.output_name().eq_ignore_ascii_case("main.rs") {
            return Err(Error::NameTaken);
        }
        if !file.is_rust() && !file.native && file.stem() == name {
            entry = Some(file);
        }
    }
    let Some(file) = entry else {
        return Err(Error::NoEntry);
    };
    let module = parse(file.src.as_bytes()).ok_or(Error::NoRoot)?;
    let root = root_name(&module).ok_or(Error::NoRoot)?;
    let project: Vec<ast::Module> = files
        .iter()
        .filter(|f| !f.is_rust() && !f.native)
        .filter_map(|f| parse(f.src.as_bytes()))
        .collect();
    let watch_clipboard = crate::codegen::app_hooks::watches_clipboard(&module)
        || crate::codegen::app_hooks::watches_clipboard_via_hooks(&module, &project);
    let mut out = String::new();
    out.push_str(&format!(
        "//! Generated by zant-tsx: the app's entry ({name}.tsx). Do not edit.\n\n"
    ));
    for file in files {
        if file.is_rust() || file.native {
            continue;
        }
        out.push_str(&format!(
            "#[path = \"{}\"] pub mod {};\n",
            file.output_name(),
            module_name(file)
        ));
    }
    out.push_str("\nfn main() -> zant::Result<()> {\n");
    out.push_str(&format!(
        "    zant::tsx::app::run::<{}::{}>({}) \n",
        crate::codegen::imports::module_name(&file.stem()),
        root,
        config_source(config, &root, watch_clipboard)
    ));
    out.push_str("}\n");
    Ok(out)
}

/// `zant::tsx::app::Config { … }` from `app.config.json` (or the defaults).
fn config_source(config: Option<&ConfigSpec>, root: &str, watch_clipboard: bool) -> String {
    let Some(config) = config else {
        return format!(
            "zant::tsx::app::Config {{ title: \"{root}\".into(), watch_clipboard: {watch_clipboard}, ..Default::default() }}"
        );
    };
    format!(
        "zant::tsx::app::Config {{\n        title: \"{}\".into(),\n        bundle_id: \"{}\".into(),\n        single_instance: {},\n        watch_clipboard: {},\n        window: zant::desktop::WindowOptions {{\n            style: zant::desktop::WindowStyle::{},\n            width: {},\n            height: {},\n            min_width: {},\n            min_height: {},\n            background: 0x{:08x},\n            resizable: {},\n            always_on_top: {},\n            movable_by_background: {},\n            center: {},\n            titlebar_height: {},\n            ..Default::default()\n        }},\n        ..Default::default()\n    }}",
        escape(&config.title),
        escape(&config.bundle_id),
        config.single_instance,
        watch_clipboard,
        style_variant(&config.window.style),
        config.window.width,
        config.window.height,
        config.window.min_width,
        config.window.min_height,
        config.window.background,
        config.window.resizable,
        config.window.always_on_top,
        config.window.movable_by_background,
        config.window.center,
        config.window.titlebar_height,
    )
}

fn style_variant(style: &str) -> &'static str {
    match style {
        "hidden-titlebar" | "hiddenTitlebar" => "HiddenTitlebar",
        "borderless" => "Borderless",
        "panel" => "Panel",
        _ => "Native",
    }
}

fn escape(value: &str) -> String {
    value.replace('\\', "\\\\").replace('"', "\\\"")
}

/// The Rust module name of a file (`src/components/TodoRow.tsx` → `todo_row`).
pub fn module_name(file: &SourceFile) -> String {
    crate::codegen::imports::module_name(&file.stem())
}

/// The default exported component's name.
fn root_name(module: &ast::Module) -> Option<String> {
    module
        .functions
        .iter()
        .find(|top| top.default)
        .map(|top| String::from_utf8_lossy(&top.func.name).into_owned())
}

fn parse(src: &[u8]) -> Option<ast::Module> {
    let src = std::str::from_utf8(src).ok()?;
    let mut parser = Parser::init(src);
    parser.parse_module().ok()
}

/// Every `.tsx` / `.ts` / `.rs` under `dir` (any depth, hidden entries
/// skipped), sorted so outputs don't depend on the file system's order.
pub fn collect(dir: &str) -> std::io::Result<Vec<String>> {
    let mut out = Vec::new();
    walk(dir, &mut out, 0)?;
    out.sort();
    Ok(out)
}

fn walk(dir: &str, out: &mut Vec<String>, depth: usize) -> std::io::Result<()> {
    if depth > 16 {
        return Ok(());
    }
    for entry in std::fs::read_dir(dir)? {
        let entry = entry?;
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            continue;
        };
        if name.is_empty() || name.starts_with('.') {
            continue;
        }
        let path = format!("{dir}/{name}");
        let file_type = entry.file_type()?;
        if file_type.is_dir() {
            walk(&path, out, depth + 1)?;
        } else if name.ends_with(".tsx") || name.ends_with(".ts") || name.ends_with(".rs") {
            out.push(path);
        }
    }
    Ok(())
}

/// The specs of native modules: `<dir>/*.ts` (not `.d.ts`; not deeper, where
/// the modules keep their internal code); `native_specs` compiles them.
pub fn collect_specs(dir: &str) -> std::io::Result<Vec<String>> {
    let mut out = Vec::new();
    for entry in std::fs::read_dir(dir)? {
        let entry = entry?;
        let name = entry.file_name();
        let Some(name) = name.to_str() else {
            continue;
        };
        if name.is_empty() || name.starts_with('.') {
            continue;
        }
        if !entry.file_type()?.is_file() {
            continue;
        }
        if !name.ends_with(".ts") || name.ends_with(".d.ts") {
            continue;
        }
        out.push(format!("{dir}/{name}"));
    }
    out.sort();
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_entry_runs_the_default_export_with_the_project_config() {
        let app = SourceFile::tsx(
            "src/App.tsx",
            "export default function Clips() { return <View/>; }",
        );
        let config = SourceFile::rust("src/app_config.rs", "pub const title = \"x\";");
        let with = main_source(&[app.clone(), config], "App", None).expect("entry");
        assert!(with.contains("#[path = \"App.rs\"] pub mod app;"), "{with}");
        assert!(
            with.contains("zant::tsx::app::run::<app::Clips>("),
            "{with}"
        );
        assert!(with.contains("title: \"Clips\".into()"), "{with}");
        let _ = &with;
        assert_eq!(
            Err(Error::NoEntry),
            main_source(std::slice::from_ref(&app), "Main", None)
        );
        let main_rs = SourceFile::rust("src/main.rs", "");
        assert_eq!(
            Err(Error::NameTaken),
            main_source(&[app, main_rs], "App", None)
        );
    }
}
